-- Seed: Director of Laboratory Services profile and its query library from the trial.
-- Generated by scripts/generate_director_seed.py from director-lab-services-tracker.xlsx.
-- Do not hand-edit; regenerate instead.
--
-- Needs the target user's id (auth.users.id). Run with psql:
--   psql "$DATABASE_URL" -v ON_ERROR_STOP=1 \
--     -c "select set_config('seed.user_id', '<USER_UUID>', false)" \
--     -f supabase/seed/director-lab-services.sql
-- Or in the Supabase SQL editor, put this line above the file contents and run both:
--   select set_config('seed.user_id', '<USER_UUID>', false);
--
-- Idempotent: running it twice does not duplicate the profile or queries.

do $seed$
declare
  v_user uuid := nullif(current_setting('seed.user_id', true), '')::uuid;
  v_profile uuid;
begin
  if v_user is null then
    raise exception 'Set seed.user_id first: select set_config(''seed.user_id'', ''<uuid>'', false);';
  end if;
  if not exists (select 1 from auth.users where id = v_user) then
    raise exception 'No auth.users row with id %. Sign in once with that account first.', v_user;
  end if;

  select id into v_profile from public.profiles
   where user_id = v_user and lower(name) = lower('Director of Laboratory Services') and deleted_at is null;

  if v_profile is null then
    insert into public.profiles
      (user_id, name, target_titles, locations, min_base_pay, must_haves, deal_breakers, plus_factors, scoring_rubric, notes)
    values (
      v_user,
      'Director of Laboratory Services',
      array['Director of Laboratory Services', 'Director of Laboratory Operations', 'Senior Director of Laboratory Services', 'Laboratory Administrator', 'Regional Laboratory Director']::text[],
      '{}'::text[],
      150000,
      '[{"key": "min_base_pay", "label": "Base pay at or above minimum", "detail": "$150,000 base. Postings whose top of range is below this are flagged as an unmet must have."}, {"key": "administrative_role", "label": "Administrative laboratory leadership role", "detail": "Target titles are administrative roles, not CLIA laboratory director roles."}]'::jsonb,
      '[]'::jsonb,
      '[{"label": "Travel"}, {"label": "Remote"}, {"label": "Hybrid"}]'::jsonb,
      '{"bands": [{"range": [9, 10], "rule": "Administrative lab director role, pay clears minimum, no unmet required credentials beyond items not on the facts sheet"}, {"range": [7, 8], "rule": "Strong match with one open question (pay not listed, low end below minimum, or details not visible)"}, {"range": [5, 6], "rule": "Good duties match but an unmet required credential, pay mostly below minimum, or contract"}, {"range": [1, 4], "rule": "Hard gap such as CLIA director credentials, or outside the target setting"}], "always_flag_as_gap": ["Any posting that requires CLIA laboratory director credentials (MD, DO, or doctoral degree)"], "facts_source": "Career facts sheet only. Never invent resume facts.", "easy_apply_default": "unknown"}'::jsonb,
      'Seeded from the trial tracker built 2026-10-24.'
    )
    returning id into v_profile;
  end if;

