    (v_user, v_profile, 'indeed', 'Director of Laboratory Operations, United States', '{"location": "United States"}'::jsonb, 'good', 1, null, null, false, 'Best Indeed query: Quest, BILH, Bayhealth, PA DOH, Ironside'),
    (v_user, v_profile, 'indeed', 'Regional Laboratory Director, United States', '{"location": "United States"}'::jsonb, 'mixed', 1, null, null, false, 'Found Self Regional, plus low pay rural director roles'),
    (v_user, v_profile, 'indeed', 'Laboratory Administrator hospital, United States', '{"location": "United States"}'::jsonb, 'noise', 1, null, null, true, 'Only clerical and assistant roles; the title Laboratory Administrator returns support jobs'),
    (v_user, v_profile, 'indeed', 'Senior Director Laboratory Services, United States', '{"location": "United States"}'::jsonb, 'mixed', 1, null, null, false, 'Repeated Quest and Bayhealth; rest pharma and research'),
    (v_user, v_profile, 'indeed', 'Administrative Director Laboratory, United States', '{"location": "United States"}'::jsonb, 'mixed', 1, null, null, false, 'Repeated BILH; rest supervisors and research admin'),
    (v_user, v_profile, 'indeed', 'System Director Laboratory, United States', '{"location": "United States"}'::jsonb, 'noise', 1, null, null, true, 'No new relevant roles'),
    (v_user, v_profile, 'indeed', 'Laboratory Director hospital MLS ASCP, remote', '{"remote": true}'::jsonb, 'noise', 1, 0, 0, true, 'Zero results'),
    (v_user, v_profile, 'indeed', 'Director Laboratory Operations, remote', '{"remote": true}'::jsonb, 'noise', 1, null, null, true, 'No lab roles; pharma and sales'),
    (v_user, v_profile, 'ziprecruiter', 'Director of Laboratory Services, min $150,000 (2 pages)', '{"min_salary": 150000, "pages": 2}'::jsonb, 'mixed', 1, null, null, false, 'WVU and LeaderStat; rest nursing and unrelated'),
    (v_user, v_profile, 'ziprecruiter', 'Director of Laboratory Operations, min $150,000', '{"min_salary": 150000}'::jsonb, 'mixed', 1, null, null, false, 'Trinity and UCSF; dental and university safety roles too'),
    (v_user, v_profile, 'ziprecruiter', 'Senior Director Laboratory Services, min $150,000', '{"min_salary": 150000}'::jsonb, 'mixed', 1, null, null, false, 'One strong hit (The Employee Connect); rest unrelated'),
    (v_user, v_profile, 'ziprecruiter', 'Regional Laboratory Director, min $150,000', '{"min_salary": 150000}'::jsonb, 'noise', 1, null, null, true, 'No lab admin roles'),
    (v_user, v_profile, 'ziprecruiter', 'Laboratory Administrator, min $150,000', '{"min_salary": 150000}'::jsonb, 'noise', 1, null, null, true, 'Nurses, CRNAs, physicians'),
