    (v_user, v_profile, 'indeed', 'Executive Director Laboratory Services, United States', '{"location": "United States"}'::jsonb, 'good', 1, null, null, false, 'Found WMC Health VP and Community Health System; executive titles surface system level roles the director queries missed'),
    (v_user, v_profile, 'indeed', 'Director of Laboratory, California', '{"location": "California"}'::jsonb, 'good', 1, null, null, false, 'Found Superfluid Dx and Community Health System'),
    (v_user, v_profile, 'indeed', 'Director of Laboratory, Texas', '{"location": "Texas"}'::jsonb, 'mixed', 1, null, null, false, 'Only low pay rural hospitals'),
    (v_user, v_profile, 'indeed', 'Director of Laboratory, Florida', '{"location": "Florida"}'::jsonb, 'noise', 1, null, null, true, 'Analytical chemistry and cannabis roles'),
    (v_user, v_profile, 'indeed', 'Director of Laboratory Services, New York / North Carolina / Ohio', '{"location": "New York / North Carolina / Ohio"}'::jsonb, 'noise', 1, null, null, true, 'State filters returned bench or research roles or nothing'),
    (v_user, v_profile, 'indeed', 'Administrative Director Laboratory Services, United States', '{"location": "United States"}'::jsonb, 'noise', 1, null, null, true, 'Managers and bench roles only'),
    (v_user, v_profile, 'ziprecruiter', 'System Director Laboratory Services, min $150,000', '{"min_salary": 150000}'::jsonb, 'noise', 1, null, null, true, 'Physician, pharmacy, and IT roles'),
    (v_user, v_profile, 'ziprecruiter', 'Laboratory Director hospital, min $150,000', '{"min_salary": 150000}'::jsonb, 'noise', 1, null, null, true, 'Only repeated LeaderStat; rest nursing'),
    (v_user, v_profile, 'indeed', 'Vice President Laboratory Services, United States', '{"location": "United States"}'::jsonb, 'mixed', 1, null, null, false, 'Found Dana-Farber VP Blood Bank; rest pharma and engineering'),
    (v_user, v_profile, 'indeed', 'Labcorp Director Operations laboratory', '{}'::jsonb, 'noise', 1, null, null, true, 'Employer name queries return few results; only a software role'),
    (v_user, v_profile, 'indeed', 'Quest Diagnostics Director Operations', '{}'::jsonb, 'mixed', 1, null, null, false, 'Repeated Quest Marlborough; other Quest director roles pay under $100,000'),
    (v_user, v_profile, 'indeed', 'Director Laboratory Outreach, United States', '{"location": "United States"}'::jsonb, 'good', 1, null, null, false, 'Found Hennepin Healthcare Laboratory Director (admin)'),
    (v_user, v_profile, 'indeed', 'Executive Director Laboratory, United States', '{"location": "United States"}'::jsonb, 'mixed', 1, null, null, false, 'Mostly repeats'),
    (v_user, v_profile, 'ziprecruiter', 'Executive Director Laboratory Services, min $150,000', '{"min_salary": 150000}'::jsonb, 'good', 1, null, null, false, 'Top hit was South Shore Health Executive Director'),
    (v_user, v_profile, 'ziprecruiter', 'Vice President Laboratory Operations, min $150,000', '{"min_salary": 150000}'::jsonb, 'mixed', 1, null, null, false, 'Sonic Healthcare VP; agricultural and food testing labs too')
  on conflict (profile_id, source, query_text) do nothing;
end;
$seed$;
